CREATE TABLE ledger_tax_financial_statements (
 id char(36) NOT NULL COMMENT '세무 재무제표 원본 고유번호', company_id varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '대상 회사', fiscal_year smallint unsigned NOT NULL COMMENT '회계연도', report_type_code varchar(30) NOT NULL COMMENT '세무 재무제표 유형', source_organization varchar(100) NOT NULL COMMENT '작성 또는 확정 기관', filing_date date DEFAULT NULL COMMENT '신고 또는 확정일', status_code varchar(20) NOT NULL DEFAULT 'DRAFT' COMMENT '자료상태(DRAFT,CONFIRMED)', note varchar(500) DEFAULT NULL COMMENT '비고', confirmed_at datetime DEFAULT NULL COMMENT '확정일시', confirmed_by varchar(100) DEFAULT NULL COMMENT '확정 Actor', created_at datetime NOT NULL COMMENT '생성일시', created_by varchar(100) NOT NULL COMMENT '생성 Actor', updated_at datetime NOT NULL COMMENT '수정일시', updated_by varchar(100) NOT NULL COMMENT '수정 Actor', PRIMARY KEY(id), UNIQUE KEY uk_ledger_tax_fs_company_year_type(company_id,fiscal_year,report_type_code), CONSTRAINT fk_ledger_tax_fs_company FOREIGN KEY(company_id) REFERENCES system_company(id), CONSTRAINT chk_ledger_tax_fs_type CHECK(report_type_code IN ('TRIAL_BALANCE','INCOME_STATEMENT','STATEMENT_POSITION','COST_STATEMENT','RETAINED_EARNINGS')), CONSTRAINT chk_ledger_tax_fs_status CHECK(status_code IN ('DRAFT','CONFIRMED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='세무사·세무서 확정 재무제표 입력 원본';

CREATE TABLE ledger_tax_financial_statement_lines (
 id char(36) NOT NULL COMMENT '세무 재무제표 행 고유번호', tax_financial_statement_id char(36) NOT NULL COMMENT '세무 재무제표 원본', sort_no int unsigned NOT NULL COMMENT '표시순서', item_code varchar(50) DEFAULT NULL COMMENT '외부 서식 항목코드', item_name varchar(200) NOT NULL COMMENT '외부 서식 과목명', account_id varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '비교 대응 계정과목', hierarchy_level tinyint unsigned NOT NULL DEFAULT 1 COMMENT '외부 서식 계층단계', current_amount decimal(18,2) NOT NULL DEFAULT 0 COMMENT '당기 세무 금액', prior_amount decimal(18,2) NOT NULL DEFAULT 0 COMMENT '전기 세무 금액', note varchar(500) DEFAULT NULL COMMENT '행 비고', created_at datetime NOT NULL COMMENT '생성일시', created_by varchar(100) NOT NULL COMMENT '생성 Actor', updated_at datetime NOT NULL COMMENT '수정일시', updated_by varchar(100) NOT NULL COMMENT '수정 Actor', PRIMARY KEY(id), KEY idx_ledger_tax_fs_lines_parent(tax_financial_statement_id,sort_no), KEY idx_ledger_tax_fs_lines_account(account_id), CONSTRAINT fk_ledger_tax_fs_lines_parent FOREIGN KEY(tax_financial_statement_id) REFERENCES ledger_tax_financial_statements(id) ON DELETE CASCADE, CONSTRAINT fk_ledger_tax_fs_lines_account FOREIGN KEY(account_id) REFERENCES ledger_accounts(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='세무 재무제표 외부 서식 행과 기업회계 계정 대응';
